 1→// Integer ranges. Ranges are half-open: they include start and exclude end.
 2→
 3→/** The integers from start up to, but not including, end, counting by step (which may be negative). */
 4→export function range(start, end, step = 1) {
 5→  if (step === 0) throw new RangeError("step must not be 0");
 6→  const out = [];
 7→  if (step > 0) {
 8→    for (let i = start; i < end; i += step) out.push(i);
 9→  } else {
10→    for (let i = start; i >= end; i += step) out.push(i);
11→  }
12→  return out;
13→}
14→
15→/** Whether n lies in [start, end). */
16→export function contains(start, end, n) {
17→  return n >= start && n < end;
18→}
